131	        if (telephoneInUse) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
135	            String lastNameKey = householdKey(owner.getLastName());
136	            String addressKey = householdKey(owner.getAddress());
137	            boolean householdInUse = this.clinicService.findAllOwners().stream()
