152	    /**
153	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
154	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
155	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
156	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
157	     *
158	     * @param telephone the raw telephone value (may be {@code null})
159	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
160	     *         a valid E.164 number
161	     */
162	    private String toE164(String telephone) {
163	        if (telephone == null) {
164	            return null;
165	        }
166	        String trimmed = telephone.trim();
167	        boolean hasCountryCode = trimmed.startsWith("+");
168	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
169	        if (hasCountryCode) {
170	            cleaned = cleaned.substring(1);
171	        }
172	        if (!cleaned.matches("[0-9]+")) {
173	            return null;
174	        }
175	        String digits;
176	        if (hasCountryCode) {
177	            digits = cleaned;
178	        } else {
179	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
180	            digits = "61" + national;
181	        }
182	        if (digits.length() < 8 || digits.length() > 15) {
183	            return null;
184	        }
185	        return "+" + digits;
186	    }
187	
188	    /**
189	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
190	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
191	     *
192	     * @param email the raw email value (must not be {@code null})
193	     * @return the trimmed, lower-cased email
194	     */
195	    private String normalizeEmail(String email) {
196	        return email.trim().toLowerCase(Locale.ROOT);
197	    }
198	
199	    /**
200	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
201	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
202	     * so that owners are compared case-insensitively with collapsed whitespace.
203	     *
204	     * @param value the raw value (must not be {@code null})
205	     * @return the normalized comparison key
206	     */
207	    private String householdKey(String value) {
208	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
209	    }
