211	    /**
212	     * Builds the customer code for a newly registered owner in the form
213	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters
214	     * of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
215	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
216	     *
217	     * @param lastName the owner's last name
218	     * @return the assigned customer code
219	     */
220	    private String nextCustomerCode(String lastName) {
221	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
222	        int sequence = this.clinicService.findAllOwners().size() + 1;
223	        return String.format(Locale.ROOT, "%s-%04d", last3, sequence);
224	    }
