238	            }
239	        }
240	        String telephone = toE164(ownerFieldsDto.getTelephone());
241	        if (telephone == null) {
242	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
243	        }
244	        currentOwner.setAddress(ownerFieldsDto.getAddress());
245	        currentOwner.setCity(ownerFieldsDto.getCity());
246	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
247	        currentOwner.setLastName(ownerFieldsDto.getLastName());
248	        currentOwner.setTelephone(telephone);
249	        currentOwner.setEmail(email);
250	        this.clinicService.saveOwner(currentOwner);
251	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
252	    }
