        boolean hasCountryCode = trimmed.startsWith("+");
        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
        if (hasCountryCode) {
            cleaned = cleaned.substring(1);
        }
        if (!cleaned.matches("[0-9]+")) {
